CREATE TABLE assessments (id uuid PRIMARY KEY, product text NOT NULL, sector text NOT NULL, target_customer text NOT NULL, budget numeric(14,2) NOT NULL, horizon_months int NOT NULL, preferred_modes jsonb NOT NULL, hs_code text, unit_value numeric(14,2), volume int, weights jsonb NOT NULL, version int NOT NULL, score_version text NOT NULL, data_version text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE regions (id text PRIMARY KEY,name text NOT NULL,component_scores jsonb NOT NULL,coverage numeric NOT NULL,source_ids jsonb NOT NULL,warnings jsonb NOT NULL);
CREATE TABLE sources (id text PRIMARY KEY,authority text NOT NULL,canonical_url text NOT NULL,passage text NOT NULL,page text NOT NULL,effective_at date,checked_at date,retrieved_at date,status text NOT NULL);
CREATE TABLE partners (id uuid PRIMARY KEY,name text NOT NULL,fictional boolean NOT NULL,region_id text NOT NULL,fit jsonb NOT NULL,evidence jsonb NOT NULL,coverage numeric NOT NULL,unknowns jsonb NOT NULL,verification_state text NOT NULL,verification_date date,missing_checks jsonb NOT NULL);
CREATE TABLE gtm_scenarios (id uuid PRIMARY KEY,assessment_id uuid REFERENCES assessments(id),assumptions jsonb NOT NULL,calculation jsonb NOT NULL,version int NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE report_snapshots (id uuid PRIMARY KEY,assessment_id uuid REFERENCES assessments(id),payload jsonb NOT NULL,version int NOT NULL,created_at timestamptz NOT NULL);
